// Unit test for flag evaluation
describe('Flag Evaluation', () => {
  it('should return correct value for per-tenant, per-environment flag', () => {
    const flag = createFlag({
      key: 'new-checkout',
      tenants: ['acme-corp'],
      environments: ['production'],
      rolloutPercentage: 50
    });

    expect(evaluate(flag, { tenantId: 'acme-corp', environment: 'production' })).toBe(true);
    expect(evaluate(flag, { tenantId: 'other-co', environment: 'production' })).toBe(false);
  });

  it('should handle percentage rollout deterministically', () => {
    const results = new Set();
    for (let i = 0; i < 100; i++) {
      const userId = `user-${i}`;
      results.add(evaluateFlag(flag, userId));
    }
    expect(results.size).toBeGreaterThan(1);
  });
});

// Integration test for multi-region propagation
describe('Multi-Region Propagation', () => {
  it('should replicate flag updates across regions within SLA', async () => {
    await adminClient.enableFlag('us-east-1', 'feature-x');
    const start = Date.now();

    await waitForPropagation('eu-west-1', 'feature-x', true, { maxWaitMs: 5000 });
    const latency = Date.now() - start;

    expect(latency).toBeLessThan(5000);
  });
});

// Race condition test
describe('Concurrent Flag Operations', () => {
  it('should handle simultaneous enable/disable correctly', async () => {
    const operations = [
      adminClient.enableFlag('feature-x'),
      adminClient.disableFlag('feature-x'),
      adminClient.enableFlag('feature-x'),
    ];

    await expect(Promise.all(operations)).resolves.not.toThrow();
    const finalState = await adminClient.getFlagState('feature-x');
    expect(finalState).toBeDefined();
  });
});
```

